import{_ as n,h as i,i as a,c as l,v as r,p as s,x as o,m,e as f,S as p}from"./chunks/framework.Dvtg8yj2.js";const x=JSON.parse('{"title":"Reformer","description":"","frontmatter":{"title":"Reformer","date":"2026-09-03T00:00:00.000Z","section":"llm"},"headers":[],"relativePath":"llm/reformer.md","filePath":"llm/reformer.md","lastUpdated":1788454257000}'),d={name:"llm/reformer.md"};function h(c,e,E,_,u,L){const t=i("Mermaid");return a(),l("div",null,[e[1]||(e[1]=r('<h1 id="reformer" tabindex="-1">Reformer <a class="header-anchor" href="#reformer" aria-label="Permalink to &quot;Reformer&quot;">​</a></h1><div class="epigraph"><p>用哈希把注意力限制在同类桶里，用可逆残差把激活从显存里拿掉：效率来自近似邻居与重算，而不是改写 softmax 核。</p><footer>—— Kitaev, Kaiser &amp; Levskaya, Reformer, ICLR 2020</footer></div><p>2019–2020 年，长序列 Transformer 同时撞上两堵墙：注意力的 \\(n^2\\) 项，以及反向传播要存下每一层激活。Kitaev、Kaiser 与 Levskaya 的 Reformer 把这两件事打包进同一篇系统论文：局部敏感哈希（LSH）注意力把每个查询的可见集缩到哈希邻居；可逆残差让前向不必保留子层输入；前馈再沿长度分块。稀疏图的一般设计见 <a href="/llm/sparse-attention-patterns">BigBird / Longformer 稀疏模式</a>；核化线性路线见 <a href="/llm/linear-attention">线性注意力</a>。本篇写 Reformer 原文选的近似与显存技巧，以及哈希与因果掩码之间的摩擦。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>若目标是把 Transformer 用到几万 token 的字符流或长文档，稠密注意力的显存先于质量爆掉。稀疏若按固定窗，远距离邻居永远进不了同一层的可见集；若按内容选邻居，又要回答「如何在次二次时间内找到近邻」。同时，即使注意力稀疏了，标准残差网络仍按层存储激活，深度与宽度会把显存第二次打满。Reformer 的命题是：用同一套实现同时打注意力复杂度与激活存储，使「长而深」在当时的单机或小集群上可行。</p><p>LSH 的经典用途是近似近邻检索。搬进注意力，意味着承认：<strong>高点积的查询–键对更可能落在同一哈希桶</strong>，因而只在桶内做 softmax 是对满注意力的内容相关近似。这个假设对、桶大小可控，复杂度接近 \\(O(n\\log n)\\) 量级（再乘桶内二次）；假设不成立，就变成随机掉边。</p><h3 id="同时打显存与注意力平方" tabindex="-1">同时打显存与注意力平方 <a class="header-anchor" href="#同时打显存与注意力平方" aria-label="Permalink to &quot;同时打显存与注意力平方&quot;">​</a></h3><p>只换 LSH 而保留标准反向，激活存储仍按 \\(O(L\\cdot n\\cdot d)\\) 涨。只上可逆残差而保留稠密注意力，\\(n^2\\) 的分数矩阵或等价算力仍在。原文把二者绑在一起，是因为它的目标场景是超长序列上的完整 Transformer，而不是给短句翻译省几个百分点。评测因此偏向 enwik8、imagenet64 一类长序列，而不是 GLUE 短句——短句上 LSH 的近似误差更可见，收益更小。</p><p><span class="marginnote">可逆网络省的是 <em>激活显存</em>，不是参数或优化器状态。Adam 的一、二阶矩仍按参数量存。把 Reformer 说成「显存随深度无关」时，应写明指激活，否则与优化器峰值对不上。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>LSH 注意力先把查询与键投到同一空间（原文常让 \\(Q=K\\) 的投影共享，否则不同投影下哈希不可比），再对每个向量抽若干随机超平面，得到哈希码，按码排序后分桶。每个位置主要与同桶（及因排序形成的块）内位置计算注意力；多轮哈希（n_rounds）用来降低漏掉真近邻的概率。桶内仍是 softmax 加权，不是核特征。为了负载，过长的桶会再切成定长块，避免最坏 \\(O(n^2)\\) 回潮。</p><p>可逆残差把一层拆成对偶分支，前向</p> \\[y_1 = x_1 + F(x_2),\\qquad y_2 = x_2 + G(y_1), \\]<p>反向由 \\(y\\) 代数恢复 \\(x\\)，因而训练时不必存 \\(x\\)。注意力与 FFN 分别充当 \\(F,G\\) 一类子层。FFN 沿序列分块计算，使中间宽 \\(4d\\) 的激活不必整段同时驻留。这三项是配套工程：哈希减边，可逆减深度方向的激活，分块减宽度方向的峰值。</p>',14)),(a(),s(p,null,{default:o(()=>[f(t,{id:"mermaid-38",class:"mermaid",graph:"flowchart%20TD%0A%20%20X%5B%22%E5%BA%8F%E5%88%97%22%5D%20--%3E%20H%5B%22LSH%20%E5%88%86%E6%A1%B6%22%5D%0A%20%20H%20--%3E%20A%5B%22%E6%A1%B6%E5%86%85%E6%B3%A8%E6%84%8F%E5%8A%9B%22%5D%0A%20%20A%20--%3E%20REV%5B%22%E5%8F%AF%E9%80%86%E6%AE%8B%E5%B7%AE%E5%86%99%E5%9B%9E%22%5D%0A%20%20REV%20--%3E%20FFN%5B%22%E5%88%86%E5%9D%97%E5%89%8D%E9%A6%88%22%5D%0A%20%20FFN%20--%3E%20Y%5B%22%E4%B8%8B%E4%B8%80%E5%B1%82%22%5D%0A"})]),fallback:o(()=>[...e[0]||(e[0]=[m(" Loading... ",-1)])]),_:1})),e[2]||(e[2]=r('<h3 id="lsh-注意力" tabindex="-1">LSH 注意力 <a class="header-anchor" href="#lsh-注意力" aria-label="Permalink to &quot;LSH 注意力&quot;">​</a></h3><p>哈希是随机的，同一输入每次前向的图可以不同，除非固定随机投影。训练因而带噪声，相当于对注意力边的数据增强；推理若重抽哈希，生成会不稳，应固定或与训练一致。多轮哈希提高召回，费用线性涨。共享 \\(Q/K\\) 投影降低表达力（查询与键不再是两套几何），却是 LSH 能工作的代价之一。这与后来 GQA 合并 KV 头不是同一动机：这里合并的是 Q 与 K 的几何，为了可比哈希。</p><h3 id="可逆残差与分块-ffn" tabindex="-1">可逆残差与分块 FFN <a class="header-anchor" href="#可逆残差与分块-ffn" aria-label="Permalink to &quot;可逆残差与分块 FFN&quot;">​</a></h3><p>可逆的数值问题是：反向重算 \\(F\\) 时，浮点误差会累积，极深或半精度时需要核对。它还强制子层写成对偶加法形式，和 Pre-LN 解码器的标准实现不完全同构，移植现代块时不能「只换注意力」。分块 FFN 与序列并行兼容，但块太小则矩阵乘效率差。原文的效率数字应在长 \\(n\\) 下读：短 \\(n\\) 上排序、哈希、可逆的开销会吃掉稀疏收益。</p><h2 id="机制" tabindex="-1">机制 <a class="header-anchor" href="#机制" aria-label="Permalink to &quot;机制&quot;">​</a></h2><p>LSH 近似的是「谁与谁算注意力」，不是近似 softmax 核的值。桶内仍可以有尖锐的权重。漏掉的真近邻永远是零权重，这一误差不可被更多层完全补回，只能靠多轮哈希或局部窗旁路。许多实现因此把邻域窗与 LSH 并在一起：近邻有确定边，远处靠哈希碰运气。这已经接近 Longformer 的「窗 + 额外边」，只是额外边由哈希而不是膨胀或全局点给出。</p><p>可逆机制与注意力近似正交。它可以接到稠密注意力上（当时的 RevNet 传统），Reformer 把它用在 Transformer 上是为了让长 \\(n\\) 的深度仍装得进卡。贡献是系统集成，不是发明可逆网络。</p><p><span class="marginnote">因果 LSH 必须禁止看未来桶成员。排序打乱位置顺序后，掩码不能再假设下标相邻即时间相邻。实现错误会泄漏未来，评测却仍可能看起来困惑度很好。因果任务上应单独测泄漏，不要只报 enwik8。</span></p><h3 id="哈希与因果的摩擦" tabindex="-1">哈希与因果的摩擦 <a class="header-anchor" href="#哈希与因果的摩擦" aria-label="Permalink to &quot;哈希与因果的摩擦&quot;">​</a></h3><p>语言建模是因果的，LSH 邻居却按内容聚，未来 token 可能与当前同桶。必须在桶内再施因果掩码，并且在构造桶时避免用未来信息做哈希——查询的哈希若依赖于尚未合法看见的键，定义就圆不回来。编码器双向任务没有这个问题，这也是为何 LSH 注意力在双向长序列上更好讲。生成任务上，逐步解码时哈希桶随新 token 变化，过去的「同桶」关系会改，和固定稀疏图不同。</p><h2 id="边界与工程取舍" tabindex="-1">边界与工程取舍 <a class="header-anchor" href="#边界与工程取舍" aria-label="Permalink to &quot;边界与工程取舍&quot;">​</a></h2><p>Reformer 没有成为现代 LLM 的默认层。原因主要在硬件与生态：按桶 gather 打散 GEMM；排序与哈希在 GPU 上不如稠密 FlashAttention 吃得饱；共享 QK 与可逆块和后来的标准 Pre-LN + RoPE + 内核栈不合。作为论文，它证明了「内容稀疏 + 激活重算」可以在 2020 年把 Transformer 推到很长的字符序列；它没有证明这是服务稠密解码器的正确内核。</p><p>近似质量依赖数据几何。若点积近邻与哈希近邻不一致（投影后各向异性严重），LSH 掉边。超参（桶大小、轮数、是否加局部窗）必须跟 \\(n\\) 一起扫。不要把复杂度写成严格线性——桶内二次与负载不均会让常数很难看。与 <a href="/llm/routing-transformer">Routing Transformer</a> 的差别是：那里用在线 k-means 学簇，这里用随机哈希；一个可训，一个固定随机投影。</p><p><span class="marginnote">引用 Reformer 来论证「稀疏注意力已解决长上下文」会过满。它解决的是 2020 年实验设定下的显存与长度；针测、指令跟随、KV 缓存服务均不在原文范围。</span></p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>Reformer 原文把 LSH 注意力、可逆残差与分块 FFN 集成到同一长序列 Transformer 里。</li><li>LSH 按内容近似邻居，桶内仍是 softmax；漏边靠多轮哈希或局部窗补。</li><li>共享 Q/K 是为了哈希可比，不是为了推理期省 KV。</li><li>可逆残差省激活显存，不省优化器状态，且与标准 Pre-LN 块不同构。</li><li>因果掩码与动态分桶是主要工程风险；双向长序列更契合其假设。</li><li>未成为现代稠密 LLM 默认内核，价值在系统证明而非当前服务栈。</li><li>出处：Kitaev, Kaiser &amp; Levskaya, <em>Reformer: The Efficient Transformer</em>, ICLR 2020。</li></ul>',16))])}const A=n(d,[["render",h]]);export{x as __pageData,A as default};
